#include "DasContainerTypes.h"
#include "Engine/World.h"
#include "DasStaticLibraryProbe.h"
#include "DasRuntime.h"
#include "DasBlueprintLibrary.h"
#include "UObject/StructOnScope.h"
#include "UObject/UnrealType.h"
#include "Modules/ModuleManager.h"
bool RunDasStaticLibraryProbe(UClass* Library,FString& Report){
 bool Good=true;auto Check=[&](bool V,const TCHAR* N){Good &= V;Report+=FString(V?TEXT("PASS "):TEXT("FAIL "))+N+TEXT("\n");};
 if(!Library || !Library->IsChildOf(UDasBlueprintLibrary::StaticClass())){Check(false,TEXT("static_library_class"));return false;}
 auto* CDO=Library->GetDefaultObject();
 auto* Add=Library->FindFunctionByName(TEXT("Add"));if(!Add){Check(false,TEXT("static_Add_missing"));return false;}
 Check(Add->HasAllFunctionFlags(FUNC_Static|FUNC_BlueprintCallable|FUNC_BlueprintPure),TEXT("static_pure_UFunction_flags"));
 FStructOnScope Sum(Add);FindFProperty<FIntProperty>(Add,TEXT("left"))->SetPropertyValue_InContainer(Sum.GetStructMemory(),7);FindFProperty<FIntProperty>(Add,TEXT("right"))->SetPropertyValue_InContainer(Sum.GetStructMemory(),5);CDO->ProcessEvent(Add,Sum.GetStructMemory());
 Check(CastFieldChecked<FIntProperty>(Add->GetReturnProperty())->GetPropertyValue_InContainer(Sum.GetStructMemory())==12,TEXT("static_Add_without_actor_or_component"));
 auto* Stats=Library->FindFunctionByName(TEXT("Stats"));FStructOnScope Values(Stats);FindFProperty<FIntProperty>(Stats,TEXT("counter"))->SetPropertyValue_InContainer(Values.GetStructMemory(),10);CDO->ProcessEvent(Stats,Values.GetStructMemory());
 Check(Stats->HasAnyFunctionFlags(FUNC_Static) && !Stats->HasAnyFunctionFlags(FUNC_BlueprintPure) && FindFProperty<FIntProperty>(Stats,TEXT("counter"))->GetPropertyValue_InContainer(Values.GetStructMemory())==13 && FindFProperty<FIntProperty>(Stats,TEXT("doubled"))->GetPropertyValue_InContainer(Values.GetStructMemory())==26,TEXT("static_out_ref_copyback"));
 auto* Label=Library->FindFunctionByName(TEXT("Label"));FStructOnScope Text(Label);FindFProperty<FStrProperty>(Label,TEXT("value"))->SetPropertyValue_InContainer(Text.GetStructMemory(),TEXT("Пример 世界"));CDO->ProcessEvent(Label,Text.GetStructMemory());Check(CastFieldChecked<FStrProperty>(Label->GetReturnProperty())->GetPropertyValue_InContainer(Text.GetStructMemory())==TEXT("Пример 世界!"),TEXT("static_Unicode_string"));
 auto* Precise=Library->FindFunctionByName(TEXT("Precise"));FStructOnScope Number(Precise);FindFProperty<FDoubleProperty>(Precise,TEXT("value"))->SetPropertyValue_InContainer(Number.GetStructMemory(),1.23456789012345);CDO->ProcessEvent(Precise,Number.GetStructMemory());Check(CastFieldChecked<FDoubleProperty>(Precise->GetReturnProperty())->GetPropertyValue_InContainer(Number.GetStructMemory())==1.23456789012345+0.25,TEXT("static_double_precision"));
 auto* Name=Library->FindFunctionByName(TEXT("EchoName"));FStructOnScope NameArgs(Name);FindFProperty<FNameProperty>(Name,TEXT("value"))->SetPropertyValue_InContainer(NameArgs.GetStructMemory(),TEXT("NativeName"));CDO->ProcessEvent(Name,NameArgs.GetStructMemory());Check(CastFieldChecked<FNameProperty>(Name->GetReturnProperty())->GetPropertyValue_InContainer(NameArgs.GetStructMemory())==TEXT("NativeName"),TEXT("static_FName"));
 auto* Ping=Library->FindFunctionByName(TEXT("Ping"));FStructOnScope PingArgs(Ping);CDO->ProcessEvent(Ping,PingArgs.GetStructMemory());Check(Ping->HasAnyFunctionFlags(FUNC_Static),TEXT("static_void_no_args"));
 auto& Runtime=FModuleManager::LoadModuleChecked<FDasRuntimeModule>(TEXT("DasRuntime"));const auto Direct=Runtime.RunFile(Runtime.ScriptPath(TEXT("dsl_math_library_call.das")),5);Check(Direct.bSucceeded && Direct.Value==24,TEXT("DAS_direct_static_calls"));if(!Direct.bSucceeded)Report+=Direct.Error;
 Runtime.ReleaseObject(GetMutableDefault<UDasBlueprintLibrary>());
 return Good;
}

bool RunDasLibraryValuesProbe(UClass* Library,UObject* Context,FString& Report){
 bool Good=true;auto Check=[&](bool V,const TCHAR* N){Good &= V;Report+=FString(V?TEXT("PASS "):TEXT("FAIL "))+N+TEXT("\n");};if(!Library)return false;auto* CDO=Library->GetDefaultObject();
 auto* Vector=Library->FindFunctionByName(TEXT("EchoVector"));FStructOnScope V(Vector);const FVector Expected(1.234567890123,2,3);*FindFProperty<FStructProperty>(Vector,TEXT("value"))->ContainerPtrToValuePtr<FVector>(V.GetStructMemory())=Expected;CDO->ProcessEvent(Vector,V.GetStructMemory());Check(*Vector->GetReturnProperty()->ContainerPtrToValuePtr<FVector>(V.GetStructMemory())==Expected,TEXT("library_vector_snapshot"));
 auto* Transform=Library->FindFunctionByName(TEXT("EchoTransform"));FStructOnScope T(Transform);const FTransform Pose(FRotator(10,20,30),FVector(4,5,6));*FindFProperty<FStructProperty>(Transform,TEXT("value"))->ContainerPtrToValuePtr<FTransform>(T.GetStructMemory())=Pose;CDO->ProcessEvent(Transform,T.GetStructMemory());Check(Transform->GetReturnProperty()->ContainerPtrToValuePtr<FTransform>(T.GetStructMemory())->Equals(Pose),TEXT("library_transform_snapshot"));
 auto* Actor=Library->FindFunctionByName(TEXT("EchoActor"));FStructOnScope A(Actor);auto* ActorObject=Cast<AActor>(Context);FindFProperty<FObjectProperty>(Actor,TEXT("value"))->SetObjectPropertyValue_InContainer(A.GetStructMemory(),ActorObject);CDO->ProcessEvent(Actor,A.GetStructMemory());Check(CastFieldChecked<FObjectProperty>(Actor->GetReturnProperty())->GetObjectPropertyValue_InContainer(A.GetStructMemory())==ActorObject,TEXT("library_typed_object"));
 auto* Class=Library->FindFunctionByName(TEXT("EchoClass"));FStructOnScope C(Class);FindFProperty<FClassProperty>(Class,TEXT("value"))->SetObjectPropertyValue_InContainer(C.GetStructMemory(),AActor::StaticClass());CDO->ProcessEvent(Class,C.GetStructMemory());Check(CastFieldChecked<FClassProperty>(Class->GetReturnProperty())->GetObjectPropertyValue_InContainer(C.GetStructMemory())==AActor::StaticClass(),TEXT("library_typed_class"));
 auto* Array=Library->FindFunctionByName(TEXT("EchoArray"));FStructOnScope Arr(Array);auto* Input=FindFProperty<FArrayProperty>(Array,TEXT("value"));*Input->ContainerPtrToValuePtr<TArray<int32>>(Arr.GetStructMemory())={2,4};CDO->ProcessEvent(Array,Arr.GetStructMemory());Check(*Array->GetReturnProperty()->ContainerPtrToValuePtr<TArray<int32>>(Arr.GetStructMemory())==TArray<int32>({2,4}),TEXT("library_array_return"));
 auto* Append=Library->FindFunctionByName(TEXT("Append"));FStructOnScope Out(Append);*FindFProperty<FArrayProperty>(Append,TEXT("values"))->ContainerPtrToValuePtr<TArray<int32>>(Out.GetStructMemory())={2,4};CDO->ProcessEvent(Append,Out.GetStructMemory());Check(*Append->GetReturnProperty()->ContainerPtrToValuePtr<int32>(Out.GetStructMemory())==3 && *FindFProperty<FArrayProperty>(Append,TEXT("values"))->ContainerPtrToValuePtr<TArray<int32>>(Out.GetStructMemory())==TArray<int32>({2,4,7}) && *FindFProperty<FStructProperty>(Append,TEXT("result"))->ContainerPtrToValuePtr<FVector>(Out.GetStructMemory())==FVector(1,2,3),TEXT("library_complex_ref_out_and_result"));
 auto* Enum=Library->FindFunctionByName(TEXT("EchoState"));FStructOnScope EnumArgs(Enum);auto* EInput=FindFProperty<FByteProperty>(Enum,TEXT("value"));EInput->SetPropertyValue_InContainer(EnumArgs.GetStructMemory(),42);CDO->ProcessEvent(Enum,EnumArgs.GetStructMemory());Check(CastFieldChecked<FByteProperty>(Enum->GetReturnProperty())->GetPropertyValue_InContainer(EnumArgs.GetStructMemory())==42,TEXT("library_authored_enum"));
 auto* Settings=Library->FindFunctionByName(TEXT("UpdateSettings"));FStructOnScope SettingsArgs(Settings);auto* SInput=FindFProperty<FStructProperty>(Settings,TEXT("value"));auto* Count=CastFieldChecked<FIntProperty>(FindDasStructField(SInput->Struct,TEXT("Count")));auto* Title=CastFieldChecked<FStrProperty>(FindDasStructField(SInput->Struct,TEXT("Title")));void* SMem=SInput->ContainerPtrToValuePtr<void>(SettingsArgs.GetStructMemory());Count->SetPropertyValue_InContainer(SMem,20);Title->SetPropertyValue_InContainer(SMem,TEXT("Авторский"));CDO->ProcessEvent(Settings,SettingsArgs.GetStructMemory());const void* SResult=Settings->GetReturnProperty()->ContainerPtrToValuePtr<void>(SettingsArgs.GetStructMemory());Check(Count->GetPropertyValue_InContainer(SResult)==22 && Title->GetPropertyValue_InContainer(SResult)==TEXT("Авторский") && Count->GetPropertyValue_InContainer(SMem)==20,TEXT("library_authored_struct_snapshot_copy"));
 auto* Map=Library->FindFunctionByName(TEXT("EchoMap"));FStructOnScope MapArgs(Map);auto* MapInput=FindFProperty<FMapProperty>(Map,TEXT("value"))->ContainerPtrToValuePtr<TMap<FString,int32>>(MapArgs.GetStructMemory());MapInput->Add(TEXT("score"),17);CDO->ProcessEvent(Map,MapArgs.GetStructMemory());const auto* MapResult=Map->GetReturnProperty()->ContainerPtrToValuePtr<TMap<FString,int32>>(MapArgs.GetStructMemory());Check(MapResult->Num()==1 && MapResult->FindRef(TEXT("score"))==17,TEXT("library_map_snapshot"));
 auto* Set=Library->FindFunctionByName(TEXT("EchoSet"));FStructOnScope SetArgs(Set);FindFProperty<FSetProperty>(Set,TEXT("value"))->ContainerPtrToValuePtr<TSet<int32>>(SetArgs.GetStructMemory())->Add(23);CDO->ProcessEvent(Set,SetArgs.GetStructMemory());const auto* SetResult=Set->GetReturnProperty()->ContainerPtrToValuePtr<TSet<int32>>(SetArgs.GetStructMemory());Check(SetResult->Num()==1 && SetResult->Contains(23),TEXT("library_set_snapshot"));
 auto* Time=Library->FindFunctionByName(TEXT("Time"));FStructOnScope TimeArgs(Time);FindFProperty<FObjectProperty>(Time,TEXT("context"))->SetObjectPropertyValue_InContainer(TimeArgs.GetStructMemory(),Context);CDO->ProcessEvent(Time,TimeArgs.GetStructMemory());Check(*Time->GetReturnProperty()->ContainerPtrToValuePtr<double>(TimeArgs.GetStructMemory())==Context->GetWorld()->GetTimeSeconds()+1.,TEXT("library_explicit_WorldContext_native_static_call"));
 auto& Runtime=FModuleManager::LoadModuleChecked<FDasRuntimeModule>(TEXT("DasRuntime"));const auto Direct=Runtime.RunFile(Runtime.ScriptPath(TEXT("dsl_library_values_calls.das")),5,false,Context);Check(Direct.bSucceeded && Direct.Value==5+int32(Context->GetWorld()->GetTimeSeconds()+1.),TEXT("library_direct_DAS_WorldContext"));if(!Direct.bSucceeded)Report+=Direct.Error;Runtime.ReleaseObject(Context);Runtime.ReleaseObject(GetMutableDefault<UDasBlueprintLibrary>());return Good;
}
